struct Line { units: Int, price: Int }

fn line_value(line: Line) -> Int {
    line.units * line.price
}

fn total_value(lines: Vec<Line>) -> Int {
    let mut total = 0
    for line in lines {
        total = total + line_value(line)
    }
    total
}

